# ---- build & append, writing after each -------------------------------------
for idx in range(13, 20):
    rec = src[idx]
    e = edits[idx]
    fin = {}
    for f in FIELDS:
        fin[f] = rec[f]
    # wholesale field sets
    for f in ["Short Hypothesis", "Abstract"]:
        if f in e:
            fin[f] = e[f]
    # related work append
    if "rw_append" in e:
        fin["Related Work"] = rec["Related Work"] + e["rw_append"]
    # experiments targeted edits
    if "exp_edits" in e:
        s = rec["Experiments"]
        for old, new in e["exp_edits"]:
            s = repl(s, old, new)
        fin["Experiments"] = s
    # risk append
    if "risk_append" in e:
        fin["Risk Factors and Limitations"] = rec["Risk Factors and Limitations"] + e["risk_append"]
    # schema check: exactly seven fields, right order
    assert list(fin.keys()) == FIELDS, fin.keys()
    assert fin["Name"] == rec["Name"]
    out.append(fin)
    tmp = SLICE + ".tmp"
    with open(tmp, "w") as fh:
        json.dump(out, fh, indent=4, ensure_ascii=False)
    os.replace(tmp, SLICE)
    print(f"appended idx {idx} ({rec['Name']}); slice now {len(out)} records")

# final verification
final = json.load(open(SLICE))
assert len(final) == 10, len(final)
names_expected = [src[i]["Name"] for i in range(10, 20)]
names_got = [r["Name"] for r in final]
assert names_got == names_expected, list(zip(names_got, names_expected))
for r in final:
    assert list(r.keys()) == FIELDS, r.keys()
print("VERIFIED: 10 records, seven-field-only, names match claim_1.json[10:20]")
print("names:", names_got)
